// Prepare pharmacy API request for auto-approved refill
const data = $input.first().json;
const patientContext = data.patientContext;
const patient = patientContext.patient;
const medication = patientContext.requestedMedication;

// Build pharmacy transmission payload (Surescripts-compatible format)
const pharmacyRequest = {
  // Patient demographics
  patient: {
    firstName: patient.name.split(' ')[0] || '',
    lastName: patient.name.split(' ').slice(1).join(' ') || '',
    dateOfBirth: patient.dateOfBirth || '',
    patientId: patient.id || ''
  },

  // Prescription details
  prescription: {
    drugName: medication.name || '',
    strength: medication.dosage || '',
    dosageForm: 'tablet', // Could be extracted from medication name
    quantity: 30, // Standard 30-day supply
    daysSupply: 30,
    refills: 3, // New refill authorization
    directions: medication.frequency || 'Take as directed',
    writtenDate: new Date().toISOString().split('T')[0]
  },

  // Prescriber
  prescriber: {
    npi: process.env.PRESCRIBER_NPI || '1234567890',
    name: patient.primaryDoctor || 'Dr. Jennifer',
    phone: process.env.OFFICE_PHONE || '+15555551234',
    fax: process.env.OFFICE_FAX || '+15555551235'
  },

  // Pharmacy (patient's preferred pharmacy from sheet, or default)
  pharmacy: {
    ncpdpId: process.env.DEFAULT_PHARMACY_NCPDP || '1234567', // 7-digit NCPDP ID
    name: process.env.DEFAULT_PHARMACY_NAME || 'CVS Pharmacy #12345',
    phone: process.env.DEFAULT_PHARMACY_PHONE || '+15555559999'
  },

  // Metadata
  metadata: {
    requestId: `REFILL-${patient.id}-${Date.now()}`,
    submittedBy: 'AI-TRIAGE-AUTO-APPROVE',
    submittedAt: new Date().toISOString(),
    aiConfidence: data.confidence || 0.0,
    aiReasoning: data.reasoning || ''
  }
};

return {
  json: {
    pharmacyRequest: pharmacyRequest,
    // Pass through for logging
    patientName: patient.name,
    patientId: patient.id,
    medicationName: medication.name,
    decision: data.decision,
    reasoning: data.reasoning
  }
};

// Prepare Slack message for doctor approval
const data = $input.first().json;
const patientContext = data.patientContext;
const patient = patientContext.patient;
const medication = patientContext.requestedMedication;
const request = patientContext.request;

const slackMessage = {
  channel: process.env.SLACK_DOCTOR_CHANNEL || '#refill-approvals',
  text: `⚠️ Prescription Refill Needs Doctor Approval`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '⚠️ Refill Request: Doctor Approval Needed'
      }
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*Patient:*\n${patient.name}`
        },
        {
          type: 'mrkdwn',
          text: `*Patient ID:*\n${patient.id}`
        },
        {
          type: 'mrkdwn',
          text: `*Last Visit:*\n${patient.lastVisitDate || 'Unknown'} (${patient.daysSinceLastVisit || '?'} days ago)`
        },
        {
          type: 'mrkdwn',
          text: `*Request:*\n"${request.rawText}"`
        }
      ]
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*Medication:*\n${medication ? medication.name : 'Not matched'}`
        },
        {
          type: 'mrkdwn',
          text: `*Dosage:*\n${medication ? medication.dosage : 'N/A'}`
        },
        {
          type: 'mrkdwn',
          text: `*Refills Left:*\n${medication ? medication.refillsRemaining : 'N/A'}`
        },
        {
          type: 'mrkdwn',
          text: `*Last Filled:*\n${medication ? medication.lastFilledDate : 'N/A'}`
        }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*AI Analysis:*\n${data.reasoning}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Recommended Action:*\n${data.recommendedAction}`
      }
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: {
            type: 'plain_text',
            text: '✅ Approve Refill'
          },
          style: 'primary',
          value: `approve_${patient.id}_${medication ? medication.name.replace(/\s/g, '_') : 'unknown'}`,
          action_id: 'approve_refill'
        },
        {
          type: 'button',
          text: {
            type: 'plain_text',
            text: '❌ Deny Refill'
          },
          style: 'danger',
          value: `deny_${patient.id}_${medication ? medication.name.replace(/\s/g, '_') : 'unknown'}`,
          action_id: 'deny_refill'
        },
        {
          type: 'button',
          text: {
            type: 'plain_text',
            text: '📞 Call Patient'
          },
          value: `call_${patient.id}`,
          action_id: 'call_patient'
        }
      ]
    }
  ]
};

return {
  json: {
    slackMessage: slackMessage,
    // Pass through for logging
    patientName: patient.name,
    patientId: patient.id,
    patientPhone: patient.phone || patient.phoneNumber || '',
    medicationName: medication ? medication.name : 'Unknown',
    decision: data.decision,
    reasoning: data.reasoning
  }
};

// Prepare urgent escalation notification
const data = $input.first().json;
const patientContext = data.patientContext;
const patient = patientContext.patient;
const medication = patientContext.requestedMedication;
const request = patientContext.request;
const flags = data.flags || [];

// Determine urgency level
const isControlled = medication && medication.isControlledSubstance;
const isOldVisit = patient.daysSinceLastVisit > 365;
const hasSafetyConcern = flags.includes('safety-concern');

let urgencyLevel = 'HIGH';
if (isControlled || hasSafetyConcern) {
  urgencyLevel = 'CRITICAL';
}

const escalationMessage = {
  urgency: urgencyLevel,
  patient: {
    name: patient.name,
    id: patient.id,
    phone: patient.phone || patient.phoneNumber || '',
    lastVisit: patient.lastVisitDate || 'Unknown',
    daysSinceVisit: patient.daysSinceLastVisit || null
  },
  request: {
    text: request.rawText,
    medication: medication ? medication.name : 'Not matched'
  },
  flags: flags,
  reasoning: data.reasoning,
  recommendedAction: data.recommendedAction,
  timestamp: new Date().toISOString()
};

// Build SMS to staff
const staffSMS = `🚨 URGENT REFILL ESCALATION

Patient: ${patient.name}
Phone: ${patient.phone || 'N/A'}
Request: "${request.rawText}"

${isControlled ? '⚠️ CONTROLLED SUBSTANCE' : ''}
${isOldVisit ? '⚠️ Last visit over 1 year ago' : ''}
${hasSafetyConcern ? '⚠️ SAFETY CONCERN' : ''}

Action: Call patient immediately

- Dr. Jennifer's Office`;

// Build Slack alert
const slackAlert = {
  channel: process.env.SLACK_URGENT_CHANNEL || '#urgent-refills',
  text: `🚨 CRITICAL: Refill Request Escalation`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '🚨 CRITICAL: Refill Request Escalation'
      }
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*Patient:*\n${patient.name}`
        },
        {
          type: 'mrkdwn',
          text: `*Phone:*\n${patient.phone || 'N/A'}`
        },
        {
          type: 'mrkdwn',
          text: `*Request:*\n"${request.rawText}"`
        },
        {
          type: 'mrkdwn',
          text: `*Medication:*\n${medication ? medication.name : 'Not matched'}`
        }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Escalation Reasons:*\n${flags.map(f => `• ${f}`).join('\n') || 'See AI reasoning below'}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*AI Analysis:*\n${data.reasoning}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Recommended Action:*\n${data.recommendedAction}`
      }
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: {
            type: 'plain_text',
            text: '📞 Call Patient Now'
          },
          style: 'danger',
          value: `call_urgent_${patient.id}`,
          action_id: 'call_urgent'
        }
      ]
    }
  ]
};

return {
  json: {
    escalationMessage: escalationMessage,
    staffSMS: staffSMS,
    slackAlert: slackAlert,
    // Pass through for logging
    patientName: patient.name,
    patientId: patient.id,
    patientPhone: patient.phone || patient.phoneNumber || '',
    medicationName: medication ? medication.name : 'Unknown',
    decision: data.decision,
    reasoning: data.reasoning,
    flags: flags
  }
};
